def _normalize_value(
    requirement: Requirement,
    observation: EvidenceObservation,
    *,
    unit_normalizer: UnitNormalizer,
    currency_table: CurrencyTable | None,
) -> tuple[ScalarValue, str | None]:
    criterion = requirement.criterion
